import{_ as l,o as e,c as t,a0 as i}from"./chunks/framework.DqMqoJl9.js";const g=JSON.parse('{"title":"前端漏洞","description":"","frontmatter":{},"headers":[],"relativePath":"interview/9-loophole.md","filePath":"interview/9-loophole.md","lastUpdated":1791426062000}'),r={name:"interview/9-loophole.md"};function a(n,o,s,c,p,d){return e(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="前端漏洞" tabindex="-1">前端漏洞 <a class="header-anchor" href="#前端漏洞" aria-label="Permalink to &quot;前端漏洞&quot;">​</a></h1><h2 id="_1-xss-跨站脚本攻击" tabindex="-1">1 XSS 跨站脚本攻击 <a class="header-anchor" href="#_1-xss-跨站脚本攻击" aria-label="Permalink to &quot;1 XSS 跨站脚本攻击&quot;">​</a></h2><p><strong>攻击类型：</strong></p><ul><li><strong>反射型：</strong> 通过 url 上的参数带入</li><li><strong>存储型：</strong> 会提交到后台，比如发表评论、使用富文本</li></ul><p><strong>攻击注入点：</strong></p><ul><li><strong>html 内容</strong> 内容是后端提交的内容，特别是后端渲染的时候</li><li><strong>html 属性</strong> 比如 img onerror 属性，是一段代码，img 加载失败的时候就会触发</li><li><strong>富文本</strong> 富文本直接保存 html 代码</li></ul><p><strong>XSS 防御：</strong></p><ol><li>html 内容，进行转义，<code>&lt;</code> <code>&gt;</code></li><li>html 属性，转义引号、空格</li><li>富文本，白名单方式，只保留安全的标签和属性</li><li>innerHtml script 不会执行，但是属性会执行</li><li>CSP http 的一个响应头，指定哪些内容可以执行</li></ol><h2 id="_2-csrf-跨站请求伪造" tabindex="-1">2 CSRF 跨站请求伪造 <a class="header-anchor" href="#_2-csrf-跨站请求伪造" aria-label="Permalink to &quot;2 CSRF 跨站请求伪造&quot;">​</a></h2><p><strong>漏洞原理：</strong></p><blockquote><p>CSRF 有两个特点：利用 cookie 自动携带的特性以及跨站攻击</p></blockquote><ul><li>浏览器已打开 B 站的页面并已登录，或者浏览器登录过 B 站，登录态还保留</li><li>这时打开了一个攻击者页面 (诱导点击的，或者是别人发的)</li><li>攻击页面带有一个表单 (ajax 可能会跨域)，会自动调用 B 站的点赞接口</li><li>这时点赞接口会自动带上你 B 站的 cookie 进行提交</li><li>回到 B 站，你会看到你在不知情的情况下点了一个赞</li></ul><p><strong>CSRF 蠕虫：</strong></p><ul><li>会自动传播</li><li>比如你的朋友圈有一个链接</li><li>你点击之后，就会自动发一条朋友圈</li><li>你的朋友又可能会点这个链接</li><li>这个就是蠕虫传播</li></ul><p><strong>防御：</strong></p><ul><li><strong>samesite：</strong> 三个值 strict(最严格，需要域名完全一致)，Lax (稍微宽松)，none (关闭)</li><li><strong>验证码和 token：</strong> 登录时生成一个 token，将 token 设置到 cookie 中同时返回给前端。 A 网站请求接口的时候会在表单内容里面带上 token，然后后端对比表单内容的 token 和 cookie 里面的 token 是否一致，来判断请求是否有效。 这个过程用户是无感的，体验比较好</li><li><strong>验证 referer：</strong> HTTP Referer 是 header 的一部分，当浏览器向 web 服务器发送请求的时候，一般会带上 Referer</li></ul><p><strong>referer 的其他用途：</strong></p><ul><li>防盗链：只允许自己的网站访问静态资源</li><li>防止恶意请求</li></ul><blockquote><p>chrome 80 后的版本 Cookie SameSite 的默认值为 Lax，也就是跨站无法带上 cookie</p></blockquote><h2 id="_3-点击劫持" tabindex="-1">3 点击劫持 <a class="header-anchor" href="#_3-点击劫持" aria-label="Permalink to &quot;3 点击劫持&quot;">​</a></h2><p><strong>攻击原理：</strong></p><ul><li>用户在登陆 A 网站的系统后，被攻击者诱惑打开第三方网站</li><li>而第三方网站通过 iframe 引入了 A 网站的页面内容</li><li>用户在第三方网站中点击某个按钮（被装饰的按钮），实际上是点击了 A 网站的按钮</li></ul><p><strong>防御：</strong></p><ul><li>可以通过 <code>top.lcation === window.location</code> 来判断页面是否被嵌套，如果被嵌套，可以更改 <code>top.location.href</code> 将父级页面跳走</li><li><code>X-Frame-Options</code>：一个 http 头，设置当前页面是否可以被 <code>iframe</code> 嵌套</li></ul><h2 id="_4-密码" tabindex="-1">4 密码 <a class="header-anchor" href="#_4-密码" aria-label="Permalink to &quot;4 密码&quot;">​</a></h2><p>常见的哈希算法，md5、sha1、sha256</p>',26)])])}const u=l(r,[["render",a]]);export{g as __pageData,u as default};
